"use client";

import * as React from "react";
import { Progress as ProgressPrimitive } from "@base-ui/react/progress";

import { cn } from "@/lib/utils";
import { oxFace, slotWell } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Margin Progress: a thin grey slot filled with the primary Button's oxblood
 * face. Leave `value` unset for an unknown amount, and a short fill pulses.
 */
const Progress = React.forwardRef<
  HTMLDivElement,
  Omit<WithClassName<ProgressPrimitive.Root.Props>, "value"> & {
    value?: ProgressPrimitive.Root.Props["value"];
  }
>(({ className, value, ...props }, ref) => (
  <ProgressPrimitive.Root
    ref={ref}
    data-slot="progress"
    value={value ?? null}
    className={cn("relative h-1.5 w-full overflow-hidden rounded-full", slotWell, className)}
    {...props}
  >
    <ProgressPrimitive.Track data-slot="progress-track" className="size-full">
      <ProgressPrimitive.Indicator
        data-slot="progress-indicator"
        className={cn(
          "h-full rounded-full transition-[width] duration-slow ease-(--ease-out)",
          oxFace,
          "data-[indeterminate]:w-1/4 data-[indeterminate]:animate-pulse",
        )}
      />
    </ProgressPrimitive.Track>
  </ProgressPrimitive.Root>
));
Progress.displayName = "Progress";

export { Progress };
